<?php
namespace App\Services\HR;use App\Models\{Employee,PayrollRun,PayrollComponent};use App\Services\Accounting\AccountingService;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;
class PayrollService{public function __construct(private AccountingService $accounting){}public function generate(int $propertyId,string $start,string $end,int $userId):PayrollRun{return DB::transaction(function()use($propertyId,$start,$end,$userId){$run=PayrollRun::create(['property_id'=>$propertyId,'reference'=>'PAY-'.date('Ym',strtotime($end)).'-'.Str::upper(Str::random(5)),'period_start'=>$start,'period_end'=>$end,'status'=>'draft','created_by'=>$userId]);$components=PayrollComponent::where('property_id',$propertyId)->where('is_active',1)->get();$gross=$deductions=$employer=0;foreach(Employee::where('property_id',$propertyId)->where('status','active')->get() as $employee){$basic=(float)$employee->basic_salary;$earn=0;$ded=0;$empCost=0;$breakdown=[];foreach($components as $c){$pivot=DB::table('employee_payroll_components')->where('employee_id',$employee->id)->where('payroll_component_id',$c->id)->whereDate('effective_from','<=',$end)->where(fn($q)=>$q->whereNull('effective_to')->orWhereDate('effective_to','>=',$start))->orderByDesc('effective_from')->first();$value=(float)($pivot->value??$c->default_value);$amount=$c->calculation==='percentage'?round($basic*$value/100,2):round($value,2);if($c->type==='earning')$earn+=$amount;elseif($c->type==='deduction')$ded+=$amount;else$empCost+=$amount;$breakdown[]=['code'=>$c->code,'name'=>$c->name,'type'=>$c->type,'amount'=>$amount];}$g=$basic+$earn;$net=max(0,$g-$ded);$run->items()->create(['employee_id'=>$employee->id,'basic_salary'=>$basic,'earnings'=>$earn,'deductions'=>$ded,'employer_costs'=>$empCost,'gross_pay'=>$g,'net_pay'=>$net,'breakdown'=>$breakdown]);$gross+=$g;$deductions+=$ded;$employer+=$empCost;}$run->update(['gross_total'=>$gross,'deduction_total'=>$deductions,'employer_cost_total'=>$employer,'net_total'=>$gross-$deductions]);return $run->load('items.employee');});}
public function approve(PayrollRun $run,int $userId):PayrollRun{if($run->status!=='draft')throw new RuntimeException('Only draft payroll can be approved.');return DB::transaction(function()use($run,$userId){$journal=$this->accounting->post($run->property_id,'payroll_run',$run->id,'Payroll '.$run->period_start->format('d M').' - '.$run->period_end->format('d M Y'),[['code'=>'5200','debit'=>(float)$run->gross_total+(float)$run->employer_cost_total],['code'=>'2250','credit'=>(float)$run->net_total],...((float)$run->deduction_total>0?[['code'=>'2260','credit'=>(float)$run->deduction_total]]:[]),...((float)$run->employer_cost_total>0?[['code'=>'2270','credit'=>(float)$run->employer_cost_total]]:[])],$userId);$run->update(['status'=>'approved','approved_by'=>$userId,'journal_entry_id'=>$journal->id]);return $run->refresh();});}
public function markPaid(PayrollRun $run,string $method,int $userId):PayrollRun{if(!in_array($run->status,['approved','partially_paid'],true))throw new RuntimeException('Payroll must be approved before payment.');return DB::transaction(function()use($run,$method,$userId){$unpaid=$run->items()->where('payment_status','unpaid')->sum('net_pay');if($unpaid<=0)return $run;$cashCode=match($method){'cash'=>'1000','mtn_momo'=>'1020','airtel_money'=>'1030',default=>'1010'};$this->accounting->post($run->property_id,'payroll_payment',$run->id,'Payroll payment',[['code'=>'2250','debit'=>(float)$unpaid],['code'=>$cashCode,'credit'=>(float)$unpaid]],$userId,'PAYMENT-'.$run->reference);$run->items()->where('payment_status','unpaid')->update(['payment_status'=>'paid','payment_method'=>$method,'paid_at'=>now()]);$run->update(['status'=>'paid','pay_date'=>now()->toDateString()]);return $run->refresh();});}}
